	if !present {
		return record1.Model[Log, model.ID[Log]]{}, foundryfault.New(foundryfault.Missing, "audit requires a stored model snapshot")
	}
	builder, err := record1.NewBuilder(item.FoundryReference(), operation, "id", policy.ID)
	if err != nil {
		return record1.Model[Log, model.ID[Log]]{}, err
	}
	var captured record1.Field[Log]
	captured, err = record1.CaptureField[Log]("id", codec.ID[Log](), changes.fields.ID, policy.ID)
	if err != nil {
		return record1.Model[Log, model.ID[Log]]{}, err
	}
	if err = builder.Add(captured); err != nil {
		return record1.Model[Log, model.ID[Log]]{}, err
	}
	captured, err = record1.CaptureField[Log]("label", codec.String[string](), changes.fields.Label, policy.Label)
	if err != nil {
		return record1.Model[Log, model.ID[Log]]{}, err
	}
	if err = builder.Add(captured); err != nil {
		return record1.Model[Log, model.ID[Log]]{}, err
	}
	return builder.Build()
